"""Independent Nasdaq TotalView-ITCH 5.0 synthetic byte builder.

This test-only module deliberately depends only on the Python standard library. It must not
import production reader or decoder code: the generated bytes are an independent oracle for
those later implementations.
"""

from __future__ import annotations

import gzip
import io
from collections import Counter
from dataclasses import dataclass
from typing import Final, Literal, TypeAlias

MessageType = Literal["S", "R", "H", "A", "F", "E", "C", "X", "D", "U", "P", "Q", "B"]
FieldValue: TypeAlias = int | str

NANOSECONDS_PER_DAY: Final = 86_400_000_000_000
MAX_FRAME_PAYLOAD: Final = 512
MESSAGE_TYPES: Final[tuple[MessageType, ...]] = (
    "S",
    "R",
    "H",
    "A",
    "F",
    "E",
    "C",
    "X",
    "D",
    "U",
    "P",
    "Q",
    "B",
)
MESSAGE_LENGTHS: Final[dict[MessageType, int]] = {
    "S": 12,
    "R": 39,
    "H": 25,
    "A": 36,
    "F": 40,
    "E": 31,
    "C": 36,
    "X": 23,
    "D": 19,
    "U": 35,
    "P": 44,
    "Q": 40,
    "B": 19,
}


class FixtureBuildError(ValueError):
    """Raised when a declarative fixture value cannot be encoded safely."""


@dataclass(frozen=True, slots=True)
class MessageDefinition:
    """One named synthetic ITCH message and its independent field values."""

    name: str
    message_type: MessageType
    fields: tuple[tuple[str, FieldValue], ...]

    def field_map(self) -> dict[str, FieldValue]:
        """Return a fresh field mapping for validation and encoding."""
        return dict(self.fields)


@dataclass(frozen=True, slots=True)
class BuiltMessage:
    """Encoded message with positions in its uncompressed framed stream."""

    definition: MessageDefinition
    payload: bytes
    message_index: int
    frame_offset: int
    payload_offset: int


@dataclass(frozen=True, slots=True)
class BuiltStream:
    """An immutable sequence of encoded messages and its framed bytes."""

    messages: tuple[BuiltMessage, ...]
    framed_bytes: bytes

    @property
    def counts_by_type(self) -> dict[str, int]:
        """Return deterministic message counts ordered by message type."""
        counts = Counter(message.definition.message_type for message in self.messages)
        return {
            message_type: counts[message_type]
            for message_type in MESSAGE_TYPES
            if counts[message_type] > 0
        }


def message(name: str, message_type: MessageType, **fields: FieldValue) -> MessageDefinition:
    """Create an immutable declarative message definition."""
    if not name or not name.isascii():
        raise FixtureBuildError("message name must be non-empty ASCII")
    if message_type not in MESSAGE_TYPES:
        raise FixtureBuildError(f"unsupported message type {message_type!r}")
    return MessageDefinition(name=name, message_type=message_type, fields=tuple(fields.items()))


def _require_fields(
    definition: MessageDefinition, required: tuple[str, ...]
) -> dict[str, FieldValue]:
    fields = definition.field_map()
    if len(fields) != len(definition.fields):
        raise FixtureBuildError(f"{definition.name}: duplicate field name")

    missing = sorted(set(required) - fields.keys())
    unknown = sorted(fields.keys() - set(required))
    if missing or unknown:
        details: list[str] = []
        if missing:
            details.append(f"missing {', '.join(missing)}")
        if unknown:
            details.append(f"unknown {', '.join(unknown)}")
        raise FixtureBuildError(f"{definition.name}: {'; '.join(details)}")
    return fields


def _unsigned(value: FieldValue, width: int, field_name: str) -> bytes:
    if isinstance(value, bool) or not isinstance(value, int):
        raise FixtureBuildError(f"{field_name} must be an integer")
    maximum = (1 << (width * 8)) - 1
    if value < 0 or value > maximum:
        raise FixtureBuildError(f"{field_name} must be in [0, {maximum}]")
    return value.to_bytes(width, byteorder="big", signed=False)


def _timestamp(value: FieldValue) -> bytes:
    if isinstance(value, bool) or not isinstance(value, int):
        raise FixtureBuildError("timestamp_ns must be an integer")
    if value < 0 or value >= NANOSECONDS_PER_DAY:
        raise FixtureBuildError(f"timestamp_ns must be in [0, {NANOSECONDS_PER_DAY - 1}]")
    return _unsigned(value, 6, "timestamp_ns")


def _alpha(value: FieldValue, width: int, field_name: str) -> bytes:
    if not isinstance(value, str):
        raise FixtureBuildError(f"{field_name} must be ASCII text")
    try:
        encoded = value.encode("ascii", errors="strict")
    except UnicodeEncodeError as error:
        raise FixtureBuildError(f"{field_name} must be ASCII text") from error
    if len(encoded) > width:
        raise FixtureBuildError(f"{field_name} must be at most {width} ASCII byte(s)")
    return encoded.ljust(width, b" ")


def _common(definition: MessageDefinition, fields: dict[str, FieldValue]) -> bytes:
    return (
        definition.message_type.encode("ascii")
        + _unsigned(fields["stock_locate"], 2, "stock_locate")
        + _unsigned(fields["tracking_number"], 2, "tracking_number")
        + _timestamp(fields["timestamp_ns"])
    )


def _encode_system_event(definition: MessageDefinition) -> bytes:
    fields = _require_fields(
        definition, ("stock_locate", "tracking_number", "timestamp_ns", "event_code")
    )
    return _common(definition, fields) + _alpha(fields["event_code"], 1, "event_code")


def _encode_stock_directory(definition: MessageDefinition) -> bytes:
    fields = _require_fields(
        definition,
        (
            "stock_locate",
            "tracking_number",
            "timestamp_ns",
            "stock",
            "market_category",
            "financial_status",
            "round_lot_size",
            "round_lots_only",
            "issue_classification",
            "issue_sub_type",
            "authenticity",
            "short_sale_threshold_indicator",
            "ipo_flag",
            "luld_reference_price_tier",
            "etp_flag",
            "etp_leverage_factor",
            "inverse_indicator",
        ),
    )
    return b"".join(
        (
            _common(definition, fields),
            _alpha(fields["stock"], 8, "stock"),
            _alpha(fields["market_category"], 1, "market_category"),
            _alpha(fields["financial_status"], 1, "financial_status"),
            _unsigned(fields["round_lot_size"], 4, "round_lot_size"),
            _alpha(fields["round_lots_only"], 1, "round_lots_only"),
            _alpha(fields["issue_classification"], 1, "issue_classification"),
            _alpha(fields["issue_sub_type"], 2, "issue_sub_type"),
            _alpha(fields["authenticity"], 1, "authenticity"),
            _alpha(
                fields["short_sale_threshold_indicator"],
                1,
                "short_sale_threshold_indicator",
            ),
            _alpha(fields["ipo_flag"], 1, "ipo_flag"),
            _alpha(fields["luld_reference_price_tier"], 1, "luld_reference_price_tier"),
            _alpha(fields["etp_flag"], 1, "etp_flag"),
            _unsigned(fields["etp_leverage_factor"], 4, "etp_leverage_factor"),
            _alpha(fields["inverse_indicator"], 1, "inverse_indicator"),
        )
    )


