def _encode_add_order(definition: MessageDefinition, *, attributed: bool) -> bytes:
    required: tuple[str, ...] = (
        "stock_locate",
        "tracking_number",
        "timestamp_ns",
        "order_reference",
        "side",
        "shares",
        "stock",
        "price4",
    )
    if attributed:
        required += ("attribution",)
    fields = _require_fields(definition, required)
    components = [
        _common(definition, fields),
        _unsigned(fields["order_reference"], 8, "order_reference"),
        _alpha(fields["side"], 1, "side"),
        _unsigned(fields["shares"], 4, "shares"),
        _alpha(fields["stock"], 8, "stock"),
        _unsigned(fields["price4"], 4, "price4"),
    ]
    if attributed:
        components.append(_alpha(fields["attribution"], 4, "attribution"))
    return b"".join(components)


