def encode_payload(definition: MessageDefinition) -> bytes:
    """Encode one definition without using production constants or decoder code."""
    encoders = {
        "S": _encode_system_event,
        "R": _encode_stock_directory,
        "H": _encode_trading_action,
        "A": lambda value: _encode_add_order(value, attributed=False),
        "F": lambda value: _encode_add_order(value, attributed=True),
        "E": _encode_order_executed,
        "C": _encode_order_executed_with_price,
        "X": _encode_order_cancel,
        "D": _encode_order_delete,
        "U": _encode_order_replace,
        "P": _encode_trade,
        "Q": _encode_cross_trade,
        "B": _encode_broken_trade,
    }
    payload = encoders[definition.message_type](definition)
    expected_length = MESSAGE_LENGTHS[definition.message_type]
    if len(payload) != expected_length:
        raise FixtureBuildError(
            f"{definition.name}: encoded {len(payload)} bytes; expected {expected_length}"
        )
    return payload


def frame_payload(payload: bytes) -> bytes:
    """Prefix one valid payload with its two-byte big-endian length."""
    if not payload:
        raise FixtureBuildError("valid frame payload must not be empty")
    if len(payload) > MAX_FRAME_PAYLOAD:
        raise FixtureBuildError(f"valid frame payload exceeds {MAX_FRAME_PAYLOAD} bytes")
    return len(payload).to_bytes(2, byteorder="big") + payload


def build_stream(definitions: tuple[MessageDefinition, ...]) -> BuiltStream:
    """Encode an ordered, non-empty synthetic message stream."""
    if not definitions:
        raise FixtureBuildError("synthetic stream must contain at least one message")

    built_messages: list[BuiltMessage] = []
    framed_parts: list[bytes] = []
    frame_offset = 0
    for message_index, definition in enumerate(definitions):
        payload = encode_payload(definition)
        framed = frame_payload(payload)
        built_messages.append(
            BuiltMessage(
                definition=definition,
                payload=payload,
                message_index=message_index,
                frame_offset=frame_offset,
                payload_offset=frame_offset + 2,
            )
        )
        framed_parts.append(framed)
        frame_offset += len(framed)
    return BuiltStream(tuple(built_messages), b"".join(framed_parts))


def deterministic_gzip(uncompressed: bytes) -> bytes:
    """Return gzip bytes with stable metadata on every supported platform."""
    destination = io.BytesIO()
    with gzip.GzipFile(
        filename="", mode="wb", fileobj=destination, compresslevel=9, mtime=0
    ) as stream:
        stream.write(uncompressed)
    return destination.getvalue()


def frame_with_observed_payload_length(payload: bytes, observed_length: int) -> bytes:
    """Create a safely bounded wrong-length frame for decoder boundary tests."""
    if isinstance(observed_length, bool) or not isinstance(observed_length, int):
        raise FixtureBuildError("observed_length must be an integer")
    if observed_length < 0 or observed_length > MAX_FRAME_PAYLOAD:
        raise FixtureBuildError(f"observed_length must be in [0, {MAX_FRAME_PAYLOAD}]")
    if observed_length <= len(payload):
        mutated_payload = payload[:observed_length]
    else:
        mutated_payload = payload + bytes(observed_length - len(payload))
    return observed_length.to_bytes(2, byteorder="big") + mutated_payload


def zero_length_frame() -> bytes:
    """Return an invalid zero-length outer frame."""
    return b"\x00\x00"


def oversized_frame_prefix() -> bytes:
    """Declare one byte above the project frame cap without allocating a payload."""
    return (MAX_FRAME_PAYLOAD + 1).to_bytes(2, byteorder="big")


def truncated_length_prefix(valid_stream: bytes) -> bytes:
    """Return a one-byte fragment of the first frame prefix."""
    if len(valid_stream) < 2:
        raise FixtureBuildError("valid_stream must contain a frame prefix")
    return valid_stream[:1]


def truncated_payload_frame(payload: bytes) -> bytes:
    """Declare a complete payload but omit its last byte."""
    if len(payload) < 2:
        raise FixtureBuildError("payload must contain at least two bytes")
    return len(payload).to_bytes(2, byteorder="big") + payload[:-1]


def replace_message_type(payload: bytes, replacement: str) -> bytes:
    """Replace the type byte while retaining a safely framed payload length."""
    if not payload:
        raise FixtureBuildError("payload must not be empty")
    encoded = _alpha(replacement, 1, "replacement")
    return encoded + payload[1:]


def truncated_gzip(compressed: bytes) -> bytes:
    """Remove the complete eight-byte gzip trailer."""
    if len(compressed) <= 8:
        raise FixtureBuildError("compressed input must contain a gzip trailer")
    return compressed[:-8]


def corrupt_gzip_checksum(compressed: bytes) -> bytes:
    """Flip one CRC-32 bit while retaining the gzip member size."""
    if len(compressed) <= 8:
        raise FixtureBuildError("compressed input must contain a gzip trailer")
    mutated = bytearray(compressed)
    mutated[-8] ^= 0x01
    return bytes(mutated)


def as_message_type(value: str) -> MessageType:
    """Narrow a checked runtime string for test-data deserialisation."""
    if value not in MESSAGE_TYPES:
        raise FixtureBuildError(f"unsupported message type {value!r}")
    return value


